t.script:
(function () {
    // Disable submit until OTP is verified
    var submitBtn = document.getElementById('wt_signup_submit_btn');
    if (submitBtn) {
        submitBtn.disabled = true;
        submitBtn.title = 'Please verify your phone number via WhatsApp OTP first.';
    }

    function getPhone() {
        var el = document.getElementById('signup_phone');
        var ph = el ? el.value.trim().replace(/[\s\-]/g, '') : '';
        if (ph && !ph.startsWith('+')) ph = '+' + ph;
        return ph;
    }

    function showMsg(elId, msg, isError) {
        var el = document.getElementById(elId);
        if (!el) return;
        el.textContent = msg;
        el.style.color = isError ? '#dc3545' : '#198754';
        el.style.display = msg ? 'block' : 'none';
    }

    window.wtSendOtp = function () {
        var phone = getPhone();
        if (!phone) {
            showMsg('wt_otp_send_msg', 'Please enter your phone number with country code.', true);
            return;
        }
        var btn = document.getElementById('wt_send_otp_btn');
        btn.disabled = true;
        btn.textContent = 'Sending…';
        showMsg('wt_otp_send_msg', '', false);

        fetch('/wa/send-otp', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call', id: 1,
                params: {phone: phone}
            })
        })
        .then(function (r) { return r.json(); })
        .then(function (data) {
            btn.disabled = false;
            btn.textContent = 'Resend OTP';
            var res = data.result || {};
            if (res.success) {
                showMsg('wt_otp_send_msg',
                    'OTP sent to ' + phone + '. Check WhatsApp.', false);
                document.getElementById('wt_otp_code_row').style.display = 'block';
                // Reset verification state on resend
                document.getElementById('wt_otp_verified_flag').value = '0';
                if (submitBtn) { submitBtn.disabled = true; }
                showMsg('wt_otp_verify_msg', '', false);
            } else {
                showMsg('wt_otp_send_msg', res.error || 'Failed to send OTP. Please try again.', true);
            }
        })
        .catch(function () {
            btn.disabled = false;
            btn.textContent = 'Send OTP';
            showMsg('wt_otp_send_msg', 'Network error. Please try again.', true);
        });
    };

    window.wtVerifyOtp = function () {
        var phone = getPhone();
        var codeEl = document.getElementById('signup_otp_code');
        var code = codeEl ? codeEl.value.trim() : '';
        if (!phone || !code) {
            showMsg('wt_otp_verify_msg', 'Enter your phone number and the OTP code.', true);
            return;
        }
        var btn = document.getElementById('wt_verify_otp_btn');
        btn.disabled = true;
        btn.textContent = 'Checking…';

        fetch('/wa/verify-otp', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0', method: 'call', id: 2,
                params: {phone: phone, code: code}
            })
        })
        .then(function (r) { return r.json(); })
        .then(function (data) {
            btn.disabled = false;
            btn.textContent = 'Verify';
            var res = data.result || {};
            if (res.valid) {
                showMsg('wt_otp_verify_msg', '✓ Phone number verified!', false);
                document.getElementById('wt_otp_verified_flag').value = '1';
                if (submitBtn) {
                    submitBtn.disabled = false;
                    submitBtn.title = '';
                }
            } else {
                showMsg('wt_otp_verify_msg', 'Invalid or expired OTP. Please request a new code.', true);
                document.getElementById('wt_otp_verified_flag').value = '0';
            }
        })
        .catch(function () {
            btn.disabled = false;
            btn.textContent = 'Verify';
            showMsg('wt_otp_verify_msg', 'Network error. Please try again.', true);
        });
    };
})();
